import{_ as a,c as i,o as r,a5 as o}from"./chunks/framework.Dl43PoGR.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{"title":"Privacy Policy","outline":"deep","prev":{"text":"Refund Policy","link":"/refund-policy"},"next":{"text":"Affiliate","link":"/affiliate"}},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),t={name:"privacy-policy.md"};function s(l,e,n,c,d,u){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p><strong>Last updated:</strong> July 26, 2025</p><p>Our website address is: <a href="/">https://ystc.in/</a>.</p><p>At <strong>YS Trading Coach</strong>, we are committed to protecting your privacy as a customer and online visitor.</p><p>We use the information we collect to provide and improve our services. Please read this Privacy Policy carefully to understand how your data is collected, used, and protected.</p><h2 id="information-we-collect" tabindex="-1">Information We Collect <a class="header-anchor" href="#information-we-collect" aria-label="Permalink to “Information We Collect”">​</a></h2><p>During your visits to our website or when using our services, we may collect:</p><ul><li>Name and company name</li><li>Email address and telephone number</li><li>Billing and mailing address</li><li>Geographic location and IP address</li><li>Survey responses and support queries</li><li>Comments and social media handles</li></ul><blockquote><p><strong>Note:</strong> Our services are not directed to persons under 18. If we discover that a child has submitted data, we will promptly delete it. Parents or guardians may contact us if they believe this has occurred.</p></blockquote><p>You may review, correct, update, or delete your data by logging into your account or contacting us directly.</p><h2 id="how-we-use-your-information" tabindex="-1">How We Use Your Information <a class="header-anchor" href="#how-we-use-your-information" aria-label="Permalink to “How We Use Your Information”">​</a></h2><p><strong>Personally Identifiable Information (PII):</strong></p><ul><li>Communicate with you about services</li><li>Provide technical support</li><li>Send updates, offers, or newsletters (only if you opt in)</li><li>Personalize your website experience</li><li>Diagnose issues and measure customer satisfaction</li></ul><p><strong>Non-Personally Identifiable Information (Non-PII):</strong></p><ul><li>Administer and improve the website</li><li>Create reports and analytics</li><li>Understand customer needs and preferences</li><li>Market products and services in aggregate</li></ul><blockquote><p>Public content (such as testimonials or blog comments) may remain visible in cached/archived copies even if you delete it.</p></blockquote><h2 id="storage-and-security" tabindex="-1">Storage and Security <a class="header-anchor" href="#storage-and-security" aria-label="Permalink to “Storage and Security”">​</a></h2><ul><li>Personal Data is stored on secure servers with restricted access.</li><li>Credit card details are <strong>encrypted before transmission</strong> and never stored.</li><li>Data is retained only as long as necessary to provide services or meet legal requirements.</li><li>In case of a security breach, we will notify you promptly as required by law.</li></ul><h2 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to “Cookies”">​</a></h2><p>Our website uses cookies to:</p><ul><li>Analyze traffic</li><li>Enable social media sharing features</li><li>Improve user experience</li></ul><p>Cookies do not access your personal files. You can disable them in your browser, but this may affect site functionality.</p><h2 id="sharing-your-information" tabindex="-1">Sharing Your Information <a class="header-anchor" href="#sharing-your-information" aria-label="Permalink to “Sharing Your Information”">​</a></h2><p>We do <strong>not sell or trade</strong> Personal Data.</p><p>We may share data only when:</p><ul><li>Required by law</li><li>Needed to process payments or deliver services</li><li>To protect our rights, trademarks, or intellectual property</li></ul><p>Any third party we share data with must agree to comply with this Privacy Policy and applicable law.</p><h2 id="legal-disclosure" tabindex="-1">Legal Disclosure <a class="header-anchor" href="#legal-disclosure" aria-label="Permalink to “Legal Disclosure”">​</a></h2><p>We may disclose information if required:</p><ul><li>By law, regulation, or legal process (court order, subpoena, etc.)</li><li>To protect the safety and rights of <strong>YS Trading Coach</strong>, our customers, or others</li><li>In the event of a merger, acquisition, or transfer of assets (under confidentiality agreements)</li></ul><h2 id="links-to-other-websites" tabindex="-1">Links to Other Websites <a class="header-anchor" href="#links-to-other-websites" aria-label="Permalink to “Links to Other Websites”">​</a></h2><p>Our website may contain third-party links.</p><ul><li>These are for your convenience only.</li><li>We are <strong>not responsible</strong> for their privacy practices.</li><li>Please review their policies before submitting personal data.</li></ul><h2 id="gdpr-compliance-eu-uk-residents" tabindex="-1">GDPR Compliance (EU &amp; UK Residents) <a class="header-anchor" href="#gdpr-compliance-eu-uk-residents" aria-label="Permalink to “GDPR Compliance (EU &amp; UK Residents)”">​</a></h2><p>If you are in the EU or UK, you have rights under <strong>GDPR</strong>.</p><p><strong>Our lawful bases for processing include:</strong></p><ul><li>Fulfilling a contract with you (e.g., sending goods/services)</li><li>Valid consent (e.g., newsletters or notifications)</li><li>Legitimate interests (e.g., analytics, service improvement)</li></ul><h2 id="your-rights-eu-uk" tabindex="-1">Your Rights (EU &amp; UK) <a class="header-anchor" href="#your-rights-eu-uk" aria-label="Permalink to “Your Rights (EU &amp; UK)”">​</a></h2><p>As an EU/UK resident, you have the right to:</p><ul><li>Be informed about how data is used</li><li>Access your data</li><li>Request corrections or updates</li><li>Object to processing</li><li>Request restriction of processing</li><li>Request deletion (“right to be forgotten”)</li><li>Request data portability</li><li>Not be subject to automated decision-making</li></ul><p>To exercise your rights, <a href="/contact">contact us</a>.</p><h2 id="withdrawing-consent" tabindex="-1">Withdrawing Consent <a class="header-anchor" href="#withdrawing-consent" aria-label="Permalink to “Withdrawing Consent”">​</a></h2><ul><li>You may withdraw consent at any time by unsubscribing from emails or contacting us.</li><li>Withdrawal may affect access to our services.</li><li>We may still process data if required for legal compliance or legitimate security reasons.</li></ul><h2 id="compliance-safeguards" tabindex="-1">Compliance &amp; Safeguards <a class="header-anchor" href="#compliance-safeguards" aria-label="Permalink to “Compliance &amp; Safeguards”">​</a></h2><ul><li>All Personal Data is treated as confidential.</li><li>We use encryption, pseudonymization, and strong cyber security measures.</li><li>Only authorized personnel have access to Personal Data.</li><li>Data is collected only for specific purposes and retained no longer than necessary.</li></ul><h2 id="your-acknowledgement" tabindex="-1">Your Acknowledgement <a class="header-anchor" href="#your-acknowledgement" aria-label="Permalink to “Your Acknowledgement”">​</a></h2><p>By providing us with your Personal Data, you consent to its transfer outside the EU/UK, provided that third parties are GDPR-compliant.</p><h2 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to “Contact Us”">​</a></h2><p>If you have questions about this Privacy Policy or your Personal Data, please <a href="/contact">contact us</a>. We aim to respond within <strong>48 hours</strong>.</p><h2 id="changes-to-privacy-policy" tabindex="-1">Changes to Privacy Policy <a class="header-anchor" href="#changes-to-privacy-policy" aria-label="Permalink to “Changes to Privacy Policy”">​</a></h2><p>We may update this policy from time to time. Changes will be effective immediately upon posting. Please check back periodically for updates.</p>',51)])])}const y=a(t,[["render",s]]);export{p as __pageData,y as default};
